  placeholder="Search anything"
  startAdornment={
    <InputAdornment position="start">
      <MagnifyingGlassIcon size={16} />
    </InputAdornment>
  }
/>

import { XIcon } from '@neoflo/atoms/icons';

<TextField
  label="Search"
  endAdornment={
    <IconButton appearance="text" size="sm" aria-label="Clear" onClick={handleClear}>
      <XIcon />
    </IconButton>
  }
/>

import InputAdornment from '@mui/material/InputAdornment';
import { EyeIcon, LockIcon } from '@neoflo/atoms/icons';

<TextField
  label="Password"
  placeholder="Enter password"
  startAdornment={
    <InputAdornment position="start">
      <LockIcon size={16} />
    </InputAdornment>
  }
  endAdornment={
    <IconButton appearance="text" size="sm" aria-label="Show password" onClick={handleToggleVisibility}>
      <EyeIcon />
    </IconButton>
  }
/>

const [view, setView] = React.useState<"list" | "grid">("list");

<ToggleButtonGroup
  exclusive
  value={view}
  onChange={(_, next) => {
    // `null` means the user deselected the only selection — ignore it.
    if (next !== null) setView(next);
  }}
  aria-label="Result layout"
>
  <ToggleButton value="list" aria-label="List"><ListIcon /></ToggleButton>
  <ToggleButton value="grid" aria-label="Grid"><GridFourIcon /></ToggleButton>
</ToggleButtonGroup>

const [pinned, setPinned] = React.useState(false);

<ToggleButton
  value="pinned"
  selected={pinned}
  onChange={() => setPinned(!pinned)}
  aria-label="Pin this thread"
>
  <PushPinIcon />
</ToggleButton>

const EXIT = 195;

{actions.map((action, index) => (
  <Zoom
    key={action.id}
    in={tab === index}
    timeout={{ enter: 225, exit: EXIT }}
    style={{ transitionDelay: tab === index ? `${EXIT}ms` : "0ms" }}
    unmountOnExit
  >
    <IconButton aria-label={action.label}>{action.icon}</IconButton>
  </Zoom>
))}
